mapper.select:
SELECT l.id, l.user_id, l.apartment_id, a.name AS apartment_name, l.room_id, r.room_number AS room_number, l.lease_start_date, l.lease_end_date, l.rent, l.deposit, l.status, l.source_type, l.create_time FROM rental_lease l LEFT JOIN rental_apartment a ON a.id = l.apartment_id AND a.is_delete = 0 LEFT JOIN rental_room r ON r.id = l.room_id AND r.is_delete = 0 WHERE l.is_delete = 0
AND l.user_id = #{query.userId}
AND l.apartment_id = #{query.apartmentId}
AND l.room_id = #{query.roomId}
AND l.status = #{query.status}
AND l.source_type = #{query.sourceType}
AND l.lease_end_date >= #{query.leaseEndDateStart}
AND l.lease_end_date <= #{query.leaseEndDateEnd}
ORDER BY l.id DESC
